/**
 * emit to subscription queries of type FindEmailMessage,
 * but only if the id matches
 *
 * @param		entity	EmailMessage
 */
	protected void emitFindEmailMessage( EmailMessage entity ) {
		LOGGER.info("handling emitFindEmailMessage" );
		
	    queryUpdateEmitter.emit(FindEmailMessageQuery.class,
	                            query -> query.getFilter().getEmailMessageId().equals(entity.getEmailMessageId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllEmailMessage
	 * 
	 * @param		entity	EmailMessage
	 */
	protected void emitFindAllEmailMessage( EmailMessage entity ) {
		LOGGER.info("handling emitFindAllEmailMessage" );
		
	    queryUpdateEmitter.emit(FindAllEmailMessageQuery.class,
	                            query -> true,
	                            entity);
	}

